def comps(L):
    H,W=len(L),7
    vis=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if L[i][j]!=0 and not vis[i][j]:
                c=L[i][j]; q=deque([(i,j)]); vis[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
