import os,glob,re,numpy as np
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    res={}
    for fn in sorted(glob.glob(d+'/../../sessions/*.jsonl')):
        txt=open(fn,encoding='utf-8').read().replace('\\n','\n')
        for m in list(re.finditer(r'(Demo pair (\d+) (?:input|output)|Test input) \((\d+)x(\d+)\):\n',txt)):
            key,h,w=m[1],int(m[3]),int(m[4])
            rows=[r.split() for r in txt[m.end():].split('\n')[:h]]
            if all(len(r)==w and all(x.isdigit() for x in r) for r in rows) and key not in res:
                res[key]=[[int(x) for x in r] for r in rows]
    return res
G=load()
def getcomps(I,bg):
    mask=I!=bg; seen=np.zeros_like(mask); out=[]
    for i in range(I.shape[0]):
        for j in range(I.shape[1]):
            if mask[i,j] and not seen[i,j]:
                q=[(i,j)]; seen[i,j]=True; s=[]
                while q:
                    x,y=q.pop(); s.append((x,y))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+da,y+db
                        if 0<=a<I.shape[0] and 0<=b<I.shape[1] and mask[a,b] and not seen[a,b]:
                            seen[a,b]=True; q.append((a,b))
                out.append(s)
    return out
